exactSources.launchDailyTask:
function launchDailyTask(t){
  if(t.type==='warmup'){
    showScreen('problems');
    startQuiz('warmup');
    return;
  }
  if(t.type==='taperReview'){
    showScreen('problems');
    startQuiz('taperreview');
    return;
  }
  if(t.type==='review'){
    const j=actionableReviewJourneys()[0];
    if(j){
      startJourneyAction(j.id);
    }else{
      showScreen('problems');
      startQuiz('review');
    }
    return;
  }
  if(t.type==='lesson'){
    startLesson(t.lessonId);
    return;
  }
  if(t.type==='prescription'){
    if(t.rx?.kind==='knowledge') startLesson(pickLessonForSkill(t.rx.cat));
    else{
      showScreen('problems');
      startQuiz(rxMode(t.rx));
    }
    return;
  }
  if(t.type==='finalFocus'){
    launchFinalFocus(t.focus);
    return;
  }
  if(t.type==='subjectB'){
    showScreen('trace');
    if(t.bmode==='trace'){
      setBMode('trace');
      if(t.bid) startBExercise(t.bid);
    }else if(t.bmode==='security'){
      setBMode('security');
      if(t.bid) startSecurityScenario(t.bid);
    }else if(t.bmode==='compound'){
      setBMode('mock');
      startCompoundChallenge();
    }else if(t.bmode==='securityMock'){
      setBMode('security');
      startSecurityMock();
    }else{
      setBMode('mock');
    }
    return;
  }
  if(t.type==='boss'){
    showScreen('problems');
    startQuiz('boss');
  }
}

exactSources.startReviewPrescription:
function startReviewPrescription(qid,reason){
  const q=originalQuestionById(qid);if(!q)return;
  const p=reasonPrescription(reason,q);
  if(reason==='知識不足'&&p.lesson){activeReviewJourneyId=qid;startLesson(p.lesson);return;}
  showScreen('problems');startQuiz(`rx:${p.kind}:${q.cat}`);
}

exactSources.startQuiz:
function startQuiz(mode){
  ensureQuestionProfile();
  quizMode=mode;
  if(String(mode).startsWith('journey:')){
    const id=String(mode).slice(8);
    const base=questionById(id);
    quizItems=base?[buildReviewItem(base)]:[];
  }else if(String(mode).startsWith('coretopic:')){
    const id=String(mode).slice(10);
    const pool=QUESTION_BANK.filter(q=>q.coreTopicId===id&&isCoreTopicImmediatePracticeQuestion(q));
    // v127: after a lesson, questions progress from foundation -> concrete application -> harder evidence.
    // Random ordering made the bridge inconsistent and could surface a generic discrimination item before an applied check.
    quizItems=orderCoreTopicPracticeQuestions(pool);
  }else if(String(mode).startsWith('corechapter:')){
    const ch=Number(String(mode).slice(12));
    quizItems=buildCoreChapterQuiz(ch);
  }else if(mode==='warmup'){
    quizItems=chooseExamWarmupQuestions(3);
  }else if(mode==='taperreview'){
    quizItems=chooseTaperReviewQuestions(5);
  }else if(mode==='review'){
    const due=dueQuestions();
    const bases=due.length ? due.slice(0,10) : chooseWeakQuestions(5);
    quizItems=bases.map(buildReviewItem);
  }else if(mode==='weak'){
    quizItems=chooseWeakQuestions(10);
  }else if(mode==='boss'){
    const days=examDaysRemaining();
    quizItems=(days!=null&&days<=14)?chooseFinalBossQuestions(5):chooseRandomBalanced(5);
  }else if(String(mode).startsWith('cogcat:')){
    const [,cat,level]=String(mode).split(':');
    const targeted=QUESTION_BANK.filter(q=>q.cat===cat&&q.cognitiveLevel===level);
    const ranked=shuffled(targeted).sort((a,b)=>reviewUrgency(b)-reviewUrgency(a));
    quizItems=ranked.slice(0,10);
    if(quizItems.length<10){
      const used=new Set(quizItems.map(q=>q.id));
      quizItems.push(...shuffled(QUESTION_BANK.filter(q=>q.cat===cat&&!used.has(q.id))).slice(0,10-quizItems.length));
    }
  }else if(String(mode).startsWith('cat:')){
    const cat=String(mode).slice(4);
    quizItems=shuffled(QUESTION_BANK.filter(q=>q.cat===cat)).slice(0,10);
  }else if(String(mode).startsWith('rx:')){
    quizItems=buildPrescriptionQuiz(mode);
  }else{
    quizItems=chooseRandomBalanced(10);
  }
  quizIndex=0;
  quizSelected=null;
  quizAnswered=false;
  quizCorrectCount=0;
  quizWrongCount=0;
  quizEarnedXp=0;
  quizPickedReason=null;
  quizRecoveredCount=0;
  stopQuestionPacer();
  sessionLog=[];

  document.getElementById('problems')?.classList.add('exercise-session-active');
  problemHub.style.display='none';
  quizResultScreen.style.display='none';
  quizSession.style.display='block';

  const titles={review:'今日の復習',taperreview:'直前復習 5問',warmup:'受験前ウォームアップ 3問',weak:'弱点10問',random:'ランダム10問',boss:'今日の総合チェック'};
  const modeTitle=String(mode).startsWith('journey:')
    ?'復習ルート・類題確認'
    :String(mode).startsWith('coretopic:')
      ?`${CORE_A_TOPIC_MAP[String(mode).slice(10)]?.title||'テーマ'}・テーマ演習`
      :String(mode).startsWith('corechapter:')
        ?`第${String(mode).slice(12)}章・章末チェック`
        :String(mode).startsWith('cogcat:')
        ?`${String(mode).split(':')[1]}・${String(mode).split(':')[2]} 集中特訓`
        :String(mode).startsWith('cat:')
          ?`${String(mode).slice(4)} 集中特訓`
        :String(mode).startsWith('rx:')
          ?prescriptionMeta(mode).title
          :titles[mode];
  document.getElementById('quizSessionTitle').textContent=modeTitle||'問題演習';
  document.getElementById('quizSessionSub').textContent=String(mode).startsWith('corechapter:')
    ?`科目A 章末統合演習・全${CORE_A_CURRICULUM.filter(t=>t.chapter===Number(String(mode).slice(12))).length}テーマ`
    :'科目A 問題演習';
  configurePrescriptionUI(mode);
  renderQuizQuestion();
  requestAnimationFrame(()=>document.getElementById('quizSession')?.scrollIntoView({block:'start',behavior:'auto'}));
}

exactSources.buildTodayTasks:
function buildTodayTasks(){
  const daysNow=examDaysRemaining();
  const totalNow=effectiveStudyMinutes();
  if(daysNow!=null&&daysNow>=0&&daysNow<=7)return buildTaperTodayTasks(daysNow,totalNow);
  const alloc=taskAllocation(totalNow);
  const routes=actionableReviewJourneys().length;
  const due=dueQuestions().length;
  const lesson=nextLessonChoice();
  const b=nextBChoice(alloc.subjectB);
  const bMinutes=(b.mode==='compound'||b.mode==='securityMock')?Math.min(20,alloc.subjectB):alloc.subjectB;
  const lessonMinutes=alloc.lesson+Math.max(0,alloc.subjectB-bMinutes);
  const weak=weakestSkill();
  const days=examDaysRemaining();
  const finalPhase=days!=null&&days<=14;

  const rxReady=window.FEQUEST_RX_READY===true;
  const rx=rxReady?recommendedPrescription():{kind:'knowledge',cat:lesson.skill,reason:'データ不足'};
  const rxMeta=rxReady?prescriptionMeta(rx):{icon:'📘',title:lesson.title,desc:'未完了教材を優先'};
  const useRx=rxReady && rx.kind!=='knowledge';

  let learnTask;
  if(lesson.complete){
    const focus=shortFinalFocusRecommendation();
    learnTask={
      type:'finalFocus',icon:focus.icon,bg:'blue',
      title:focus.title,desc:focus.desc,
      minutes:lessonMinutes,focus
    };
  }else if(useRx){
    learnTask={
      type:'prescription',icon:rxMeta.icon,bg:'blue',
      title:rxMeta.title,desc:`原因「${rx.reason}」に合わせて自動処方`,
      minutes:lessonMinutes,rx
    };
  }else{
    learnTask={
      type:'lesson',icon:'📘',bg:'blue',
      title:lesson.title,desc:`${lesson.skill}・未完了教材を優先`,
      minutes:lessonMinutes,lessonId:lesson.id
    };
  }

  return [
    {
      type:'review',icon:'🧠',bg:'green',
      title:'記憶の復習',
      desc:routes?`復習ルート ${routes}件を優先`:due?`復習期限の問題 ${due}問を優先`:`今日の復習期限はなし。「${weak}」を補強`,
      minutes:alloc.review
    },
    learnTask,
    {
      type:'subjectB',icon:'💻',bg:'purple',
      title:b.mode==='trace'?`プログラムトレース：${b.title}`:b.mode==='security'?`セキュリティ：${b.title}`:b.mode==='compound'?`複合演習：${b.title}`:b.mode==='securityMock'?b.title:`実戦：${b.title}`,
      desc:b.mode==='trace'?'科目B アルゴリズム':b.mode==='security'?'科目B 情報セキュリティ':b.mode==='compound'?'科目B アルゴリズム・20分実戦':b.mode==='securityMock'?'科目B セキュリティ・20分実戦':'科目B 実戦',
      minutes:bMinutes,bmode:b.mode,bid:b.id
    },
    {
      type:'boss',icon:'👑',bg:'yellow',
      title:finalPhase?'直前総合チェック':'今日の総合チェック',
      desc:finalPhase?'判断3問＋適用2問・分野を散らして5問':'全分野から5問・仕上げチェック',
      minutes:alloc.boss
    }
  ];
}

exactSources.taskAllocation:
function taskAllocation(total){
  total=Number(total)||effectiveStudyMinutes();const days=examDaysRemaining();
  if(days!=null&&days>=0&&days<=6)return taperTaskAllocation(total,days);
  if(days==null){if(total===30)return {review:5,lesson:10,subjectB:10,boss:5};if(total===45)return {review:5,lesson:15,subjectB:15,boss:10};if(total===90)return {review:15,lesson:30,subjectB:30,boss:15};if(total===60)return {review:10,lesson:20,subjectB:20,boss:10};}
  return allocateByRatios(total,examStudyPhase(days).ratios);
}

exactSources.startJourneyAction:
function startJourneyAction(id){
  const j=journeyFor(id);if(!j)return;
  if(j.stage==='relearn'&&j.lessonId){activeReviewJourneyId=id;startLesson(j.lessonId);return;}
  if(j.stage==='spaced'&&j.due>localDateISO(0)){popToast(`${j.due} に再確認します`);return;}
  showScreen('problems');startQuiz('journey:'+id);
}

